            .AddNode("owner", "Platform Team\nBusiness Owner", 790, 112, TopologyNodeKind.Team, TopologyHealthStatus.Healthy, subtitle: "primary owner\non-call active", width: 214, height: 90, symbol: "OWN", iconId: "chartforgex-people-org-workflow:team", color: "#F97316")
