            .AddEdge("identity-platform", "identity", "platform", "authenticates", TopologyEdgeKind.Dependency, TopologyHealthStatus.Healthy, VisualLinkDirection.Forward, TopologyEdgeRouting.Orthogonal, "OIDC")
            .AddEdge("database-platform", "database", "platform", "serves data", TopologyEdgeKind.Dependency, TopologyHealthStatus.Warning, VisualLinkDirection.Forward, TopologyEdgeRouting.Orthogonal, "lag 8m")
            .AddEdge("platform-queue", "platform", "queue", "publishes", TopologyEdgeKind.DataFlow, TopologyHealthStatus.Healthy, VisualLinkDirection.Forward, TopologyEdgeRouting.Orthogonal, "exports")
            .AddEdge("owner-platform", "owner", "platform", "owns", TopologyEdgeKind.Ownership, TopologyHealthStatus.Healthy, VisualLinkDirection.Forward, TopologyEdgeRouting.Orthogonal, "primary")
            .AddEdge("platform-consumer", "platform", "consumer", "feeds", TopologyEdgeKind.DataFlow, TopologyHealthStatus.Healthy, VisualLinkDirection.Forward, TopologyEdgeRouting.Orthogonal, "scheduled")
            .AddEdge("platform-finding", "platform", "finding", "has risk", TopologyEdgeKind.Dependency, TopologyHealthStatus.Critical, VisualLinkDirection.Forward, TopologyEdgeRouting.Orthogonal, "4 signals")
            .AddEdge("database-finding", "database", "finding", "contributes", TopologyEdgeKind.Dependency, TopologyHealthStatus.Warning, VisualLinkDirection.Forward, TopologyEdgeRouting.Orthogonal, "replica lag")
            .UpdateEdge("identity-platform", e => e.SourcePort(TopologyEdgePort.Right).TargetPort(TopologyEdgePort.Left))
            .UpdateEdge("database-platform", e => e.SourcePort(TopologyEdgePort.Right).TargetPort(TopologyEdgePort.Left))
            .UpdateEdge("platform-queue", e => e.SourcePort(TopologyEdgePort.Top).TargetPort(TopologyEdgePort.Bottom))
            .UpdateEdge("owner-platform", e => e.SourcePort(TopologyEdgePort.Left).TargetPort(TopologyEdgePort.Right))
