            .EdgeRouteLane("platform-consumer", 24)
            .UpdateEdge("identity-platform", e => e.LabelOffsetX(-22).LabelOffsetY(12))
            .UpdateEdge("database-platform", e => e.LabelOffsetX(-28).LabelOffsetY(-8))
