            .UpdateEdge("owner-platform", e => e.LabelOffsetX(20).LabelOffsetY(12))
            .UpdateEdge("platform-consumer", e => e.LabelOffsetX(10).LabelOffsetY(-18))
            .UpdateEdge("platform-finding", e => e.LabelOffsetX(-72).LabelOffsetY(0))
            .UpdateEdge("database-finding", e => e.LabelOffsetX(-42).LabelOffsetY(28))
            .UpdateEdge("platform-consumer", e => e.LineStyle(TopologyEdgeLineStyle.Dashed))
            .UpdateEdge("platform-finding", e => e.LineStyle(TopologyEdgeLineStyle.Dotted))
            .UpdateEdge("database-finding", e => e.LineStyle(TopologyEdgeLineStyle.Dotted))
            .UpdateEdge("identity-platform", e => e.Color("#2563EB"))
            .UpdateEdge("database-platform", e => e.Color("#2563EB"))
