            .UpdateEdge("owner-platform", e => e.Color("#F97316"))
            .UpdateEdge("platform-consumer", e => e.Color("#8B5CF6"))
            .UpdateEdge("platform-finding", e => e.Color("#EF4444"))
            .UpdateEdge("database-finding", e => e.Color("#EF4444"));
